  "mainEntity": [
    {
      "@type": "Question",
      "name": "什麼是骨灰鑽石／生命鑽石？",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "生命鑽石以親人毛髮或骨灰培育而成；骨灰約需 3 至 5 公克、毛髮約一顆雞蛋大小。樣本在台灣在地實驗室處理，不送海外。"
      }
    },
    {
      "@type": "Question",
      "name": "骨灰份量不夠怎麼辦？",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "若不確定份量是否足夠，請先透過官方 LINE 與顧問確認，不需要先寄送樣本。顧問會依實際狀況給建議。"
      }
    },
    {
      "@type": "Question",
      "name": "有國際鑑定嗎？",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "每顆附銘印保證卡；0.20 克拉以上可代送 GIA 或 IGI 國際鑑定（費用另計），讓珍藏在傳承時有正式身分證明。"
      }
    },
    {
      "@type": "Question",
      "name": "寵物骨灰也能做嗎？",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "可以。寵物骨灰同樣可走生命鑽石流程；若以毛髮紀念毛孩，也可參考寵物鑽石系列。"
      }
    }
  ]
}

